            tos[i] = addr;
            vals[i] = uint256(keccak256(abi.encodePacked(h, i))) % 100000;
        }

        bool ok;
        bool ret;
        try c.transfer(from, address(callee), tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        assertTrue(ok && ret);
    }
}

